+    @Test
+    public static void testNestedBranches(boolean first, boolean second) {
+        IntVector value = IntVector.fromArray(IntVector.SPECIES_128, A, 0)
+                .add(IntVector.fromArray(IntVector.SPECIES_128, B, 0));
